// This schema drives both the vendor form and server validation for every category.
const field = (key, label, type = "text", options) => ({
  key,
  label,
  type,
  ...(options ? { options } : {}),
});
const select = (key, label, options) => field(key, label, "select", options);
const num = (key, label) => field(key, label, "number");
const bool = (key, label) => field(key, label, "boolean");
const text = (key, label) => field(key, label, "textarea");
